// Canvas Dodge game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

const player = { w: 40, h: 20, x: canvas.width/2 - 20, y: canvas.height - 30, speed: 5 };
let asteroids = [];
let lives = 3;
let score = 0;
let frame = 0;
let gameOver = false;

function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  asteroids.push({ x: Math.random() * (canvas.width - size), y: -size, size, speed: 2 + frame * 0.001 });
}

function update() {
  if (gameOver) return;
  // player movement
  if (keys['ArrowLeft']) player.x = Math.max(0, player.x - player.speed);
  if (keys['ArrowRight']) player.x = Math.min(canvas.width - player.w, player.x + player.speed);

  // asteroids
  asteroids.forEach(a => a.y += a.speed);
  // remove passed asteroids & increase score
  asteroids = asteroids.filter(a => {
    if (a.y > canvas.height) { score++; return false; }
    // collision
    if (a.x < player.x + player.w && a.x + a.size > player.x && a.y < player.y + player.h && a.y + a.size > player.y) {
      lives--; if (lives <= 0) gameOver = true;
      return false; // remove collided asteroid
    }
    return true;
  });

  // spawn new asteroids over time
  if (frame % 60 === 0) spawnAsteroid();
  frame++;
}

function draw() {
  ctx.clearRect(0,0,canvas.width,canvas.height);
  // player ship (triangle)
  ctx.fillStyle = 'cyan';
  ctx.beginPath();
  ctx.moveTo(player.x, player.y + player.h);
  ctx.lineTo(player.x + player.w/2, player.y);
  ctx.lineTo(player.x + player.w, player.y + player.h);
  ctx.closePath();
  ctx.fill();
  // asteroids
  ctx.fillStyle = 'gray';
  asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.size, a.size));
  // HUD
  ctx.fillStyle = 'white';
  ctx.font = '16px monospace';
  ctx.fillText(`Lives: ${lives}`, 10, 20);
  ctx.fillText(`Score: ${score}`, 10, 40);
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px monospace';
    ctx.fillText('Game Over', canvas.width/2 - 120, canvas.height/2);
  }
}

function loop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

loop();
